#!/usr/bin/env bash
# recipes/crate-windows-x86-64-msvc--0-52-0/build.sh -- stage the windows_x86_64_msvc 0.52.0 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/windows_x86_64_msvc-0.52.0"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"dff9641d1cd4be8d1a070daf9e3773c5f67e78b4d9d42263020c057706765c04"}\n' > "${dest}/.cargo-checksum.json"
